import { Controller, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: AI 처리는 외부로 반출하지 않고 서버 내부 규칙으로만 만든다.
// 가정: 추천 문구는 최대 5개까지 돌려준다.
const MAX_PHRASES = 5;

function escapeHtml(text: string): string {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function formIdOf(value: unknown): number {
  const id = Number(value);
  if (value === null || value === undefined || value === '' || !Number.isInteger(id) || id <= 0) {
    throw new ApiError(400, 'VALIDATION_FAILED', '결재양식을 선택해 주세요.');
  }
  return id;
}

async function findForm(db: { query: (sql: string, params: Record<string, unknown>) => Promise<any[]> }, id: number) {
  const rows = await db.query(
    'SELECT approval_form_id AS "approvalFormId", form_name AS "formName" FROM approval_form WHERE approval_form_id = CAST(:id AS bigint)',
    { id },
  );
  if (rows.length === 0) {
    throw new ApiError(404, 'APPROVAL_FORM_NOT_FOUND', '선택한 결재양식을 찾을 수 없습니다.');
  }
  return rows[0] as { approvalFormId: number; formName: string };
}

@Controller('api/v1')
export class FnSfr04402Controller {
  @Post('/approval-documents/draft-assist')
  @HttpCode(200)
  async generateApprovalDocumentDraft(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const formId = formIdOf(data['approvalFormId']);
    const raw = data['requestContent'];
    if (raw !== undefined && raw !== null && typeof raw !== 'string') {
      throw new ApiError(400, 'VALIDATION_FAILED', '작성 요청 내용 형식이 올바르지 않습니다.');
    }
    const content = typeof raw === 'string' ? raw.trim() : '';
    if (content === '') {
      throw new ApiError(422, 'REQUEST_CONTENT_EMPTY', '작성 요청 내용을 입력해 주세요.');
    }
    return transaction(async (db) => {
      const form = await findForm(db, formId);
      try {
        const lines = content
          .split(/\r?\n/)
          .map((line) => line.trim())
          .filter((line) => line !== '');
        const parts: string[] = [];
        parts.push('<h2>' + escapeHtml(form.formName) + '</h2>');
        parts.push('<p>아래와 같이 보고드리오니 검토 후 결재하여 주시기 바랍니다.</p>');
        parts.push('<h3>목적 및 핵심 내용</h3>');
        for (const line of lines) {
          parts.push('<p>' + escapeHtml(line) + '</p>');
        }
        parts.push('<p>이상입니다.</p>');
        return { draftBody: parts.join('\n') };
      } catch (e) {
        throw new ApiError(502, 'AI_DRAFT_GENERATION_FAILED', 'AI 초안 생성에 실패했습니다. 직접 작성해 주세요.');
      }
    });
  }

  @Post('/approval-documents/phrase-suggestions')
  @HttpCode(200)
  async suggestApprovalDocumentPhrases(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const formId = formIdOf(data['approvalFormId']);
    const raw = data['body'];
    if (raw !== undefined && raw !== null && typeof raw !== 'string') {
      throw new ApiError(400, 'VALIDATION_FAILED', '문서 본문 형식이 올바르지 않습니다.');
    }
    const body = typeof raw === 'string' ? raw : '';
    return transaction(async (db) => {
      const form = await findForm(db, formId);
      try {
        const phrases: string[] = [];
        if (body.trim() === '') {
          phrases.push('아래와 같이 ' + form.formName + '을(를) 올리오니 검토 후 결재하여 주시기 바랍니다.');
          phrases.push('관련 내용을 다음과 같이 보고드립니다.');
        } else {
          if (body.indexOf('목적') < 0) {
            phrases.push('본 건의 목적은 다음과 같습니다.');
          }
          if (body.indexOf('기대') < 0) {
            phrases.push('이를 통해 업무 효율 향상을 기대합니다.');
          }
          if (body.indexOf('첨부') < 0) {
            phrases.push('세부 내용은 첨부 자료를 참고하여 주시기 바랍니다.');
          }
          if (body.indexOf('이상입니다') < 0) {
            phrases.push('이상입니다.');
          }
        }
        phrases.push('검토 후 승인하여 주시기 바랍니다.');
        return { phrases: phrases.slice(0, MAX_PHRASES) };
      } catch (e) {
        throw new ApiError(502, 'AI_PHRASE_SUGGESTION_FAILED', '문구 추천 생성에 실패했습니다. 직접 작성해 주세요.');
      }
    });
  }
}

