import { useState } from 'react';
import { call, Form, Field, LookupSelect, TextInput, ErrorText } from '../kit';
import type { PageProps } from '../kit';

export default function FnSfr04402Page({ role, notify }: PageProps) {
  const [formId, setFormId] = useState<number | string>('');
  const [requestContent, setRequestContent] = useState('');
  const [body, setBody] = useState('');
  const [phrases, setPhrases] = useState<string[]>([]);
  const [phraseAsked, setPhraseAsked] = useState(false);

  async function generate() {
    if (formId === '') {
      throw new Error('결재양식을 선택해 주세요.');
    }
    if (requestContent.trim() === '') {
      throw new Error('작성 요청 내용을 입력해 주세요.');
    }
    const res = await call<{ draftBody: string }>(
      'POST',
      '/approval-documents/draft-assist',
      role,
      { approvalFormId: formId, requestContent },
    );
    setBody(res.draftBody);
    notify('기안문 초안을 만들었습니다. 내용을 확인하고 수정해 주세요.');
  }

  async function suggest() {
    if (formId === '') {
      throw new Error('결재양식을 선택해 주세요.');
    }
    const res = await call<{ phrases: string[] }>(
      'POST',
      '/approval-documents/phrase-suggestions',
      role,
      { approvalFormId: formId, body },
    );
    setPhrases(res.phrases);
    setPhraseAsked(true);
    notify('추천 문구를 불러왔습니다.');
  }

  function addPhrase(phrase: string) {
    setBody(body === '' ? phrase : body + '\n' + phrase);
    notify('추천 문구를 본문에 넣었습니다.');
  }

  return (
    <div className="doc">
      <section className="box">
        <h2>AI 작성 지원</h2>
        <Form onSubmit={generate} submit="초안 만들기" note="초안은 자동으로 상신되지 않습니다. 내용을 확인하고 수정한 뒤 기안문에 반영해 주세요.">
          <Field label="결재양식" required>
            <LookupSelect table="approval_form" role={role} value={formId} onChange={setFormId} placeholder="결재양식 선택" />
          </Field>
          <Field label="제목·목적·핵심 내용" required wide hint="작성하려는 기안문의 제목, 목적, 핵심 내용을 적어 주세요.">
            <TextInput value={requestContent} onChange={setRequestContent} multiline placeholder="예: 신규 장비 구매 건 - 노후 장비 교체를 위해 3대 구매 요청" />
          </Field>
        </Form>
      </section>

      <section className="box">
        <h2>기안문 본문</h2>
        <Field label="문서 본문" wide hint="초안과 추천 문구를 직접 고쳐 쓸 수 있습니다.">
          <TextInput value={body} onChange={setBody} multiline placeholder="초안을 만들거나 직접 작성해 주세요." />
        </Field>
      </section>

      <section className="box">
        <h2>추천 문구</h2>
        <Form onSubmit={suggest} submit="문구 추천 받기">
          {phraseAsked && phrases.length === 0 ? (
            <ErrorText text="추천할 문구가 없습니다. 본문을 더 작성한 뒤 다시 요청해 주세요." />
          ) : null}
          {phrases.map((phrase, i) => (
            <p key={i}>
              {phrase}{' '}
              <button type="button" className="ghost" onClick={() => addPhrase(phrase)}>본문에 넣기</button>
            </p>
          ))}
        </Form>
      </section>
    </div>
  );
}
